137.         proof_decl! {
138.             let ghost g_old = self@;
139.             let ghost pre_sb = self.bitmap@.set_bits;
140.             let ghost pre_nb = self.bitmap@.num_bits;
141.             let ghost pre_rc = self.refcount@;
142.         }
143.         proof! {
144.             lemma_view_of(self);
145.             assert(spec_refcount_seq(self) == pre_rc);
146.             assert(g_old == view_of(pre_sb, pre_nb, pre_rc));
147.         }
148.         let frame_number: usize = match self.bitmap.alloc() {
149.             Ok(index) => index,
150.             Err(error) => {
151.                 proof! {
152.                     // The bitmap is full (every bit set), so no frame is free.
153.                     lemma_view_of(self);
154.                     assert(spec_refcount_seq(self) == pre_rc);
155.                     assert(self@ == g_old);
156.                     assert(self.bitmap@.is_full());
157.                     assert(g_old.free_frames =~= Set::<int>::empty()) by {
158.                         assert forall|a: int| #[trigger] g_old.free_frames.contains(a)
159.                             implies false by {
160.                             let i = choose|i: int|
161.                                 0 <= i < pre_nb && !pre_sb.contains(i) && a == frame_addr_of(i);
162.                             assert(0 <= i < pre_nb && !pre_sb.contains(i));
163.                             assert(self.bitmap@.set_bits.contains(i));
164.                         }
165.                     }
166.                 }
167.                 #[cfg(not(verus_keep_ghost))]
168.                 error!("{error:?}");
